-- 2. サンプル問題の追加
INSERT INTO public.questions (category_id, content, options, answer, explanation)
VALUES 
  -- 【カテゴリ1】クラウドの基本概念
  ('11111111-1111-1111-1111-111111111111', 'オンプレミスのサーバー購入費用など、初期にかかる大規模な投資（資産）を何と呼びますか？', '["OpEx (運用費用)", "CapEx (資本的支出)", "TCO (総所有コスト)", "ROI (投資利益率)"]'::jsonb, 'CapEx (資本的支出)', 'サーバーやハードウェアなどの固定資産を一括で購入する費用のことをCapEx（Capital Expenditure: 資本的支出）と呼びます。クラウドへの移行によってこれらを「OpEx（従量課金の運用費用）」に転換できます。'),
  ('11111111-1111-1111-1111-111111111111', 'Google Cloud における「責任共有モデル」に基づき、IaaS (Compute Engine など) を利用する際に「お客様（ユーザー）」側が責任を持つ必要があるのは次のうちどれですか？', '["データセンターの物理的セキュリティ", "ハイパーバイザ（仮想化層）のパッチ適用", "ゲストOSとアプリケーションのパッチ適用", "専用ハードウェアの電源管理"]'::jsonb, 'ゲストOSとアプリケーションのパッチ適用', 'IaaSモデルでは、ハードウェアや物理ネットワーク、仮想化基盤はGoogleが管理しますが、ゲストOS（WindowsやLinux）、アプリケーション、顧客データの保護はユーザー側の責任となります。'),
  ('11111111-1111-1111-1111-111111111111', 'Google Cloud リソースをグローバルに展開する際の基本単位であり、同一リージョン内で物理的に隔離された障害ドメインを何と呼びますか？', '["Region (リージョン)", "Zone (ゾーン)", "Project (プロジェクト)", "Cluster (クラスター)"]'::jsonb, 'Zone (ゾーン)', 'Zone（ゾーン）は、地理的領域であるRegion（リージョン）の内部にあり、インフラが物理的に独立している障害ドメインのことです。'),

  -- 【カテゴリ2】Google Cloud インフラストラクチャ
  ('22222222-2222-2222-2222-222222222222', 'PaaS (Platform as a Service) に分類され、開発者がインフラの管理を気にせずウェブアプリケーションのデプロイやスケーリングに集中できるサービスはどれですか？', '["Compute Engine", "App Engine", "Google Kubernetes Engine (GKE)", "Cloud Storage"]'::jsonb, 'App Engine', 'App Engineは、インフラの管理なしにウェブアプリケーションとモバイルバックエンドを構築し、スケールさせることができるフルマネージドのサーバーレス・プラットフォーム(PaaS)です。'),
  ('22222222-2222-2222-2222-222222222222', '構造化されていないデータ（画像、動画、バックアップデータなど）を安価かつ大容量に保存するのに最適なサービスはどれですか？', '["Cloud SQL", "Cloud Spanner", "Cloud Storage", "Persistent Disk"]'::jsonb, 'Cloud Storage', 'Cloud Storageは、あらゆる種類・あらゆる規模の非構造化データ（オブジェクト）を保存するために世界中で使用される、耐久性の高いオブジェクト・ストレージサービスです。'),
  ('22222222-2222-2222-2222-222222222222', 'Dockerコンテナをパッケージ化し、HTTPリクエストをトリガーにしてステートレスなアプリケーションを実行・自動スケールさせるサーバーレス製品はどれですか？', '["Cloud Functions", "Cloud Run", "Virtual Machine", "Bare Metal Solution"]'::jsonb, 'Cloud Run', 'Cloud Runは、コンテナ化されたアプリケーションをサーバーレス環境で迅速にデプロイし、リクエスト数に応じて自動的にゼロからスケールアウトできるサービスです。'),

  -- 【カテゴリ3】AI・データ分析とモダンアプリ
  ('33333333-3333-3333-3333-333333333333', 'ペタバイト規模のデータを高速に分析可能な、サーバーレスでスケーラブルなエンタープライズ向けデータウェアハウスはどれですか？', '["BigQuery", "Cloud SQL", "Firestore", "Cloud Bigtable"]'::jsonb, 'BigQuery', 'BigQueryは、Googleインフラのもつ強みを活かして超高速にSQLクエリを実行できる、フルマネージドのエンタープライズ・データウェアハウスです。機械学習機能(BigQuery ML)も内蔵しています。'),
  ('33333333-3333-3333-3333-333333333333', '統一されたUI・APIを備え、機械学習モデルの構築、トレーニング、デプロイメントを効率化するためのAIプラットフォームはどれですか？', '["Vision API", "TensorFlow", "Vertex AI", "Apigee"]'::jsonb, 'Vertex AI', 'Vertex AIは、Googleの最新の機械学習エンドツーエンドプラットフォームです。事前学習済みAPIの利用から、独自モデルの構築（AutoML / カスタムトレーニング）、デプロイまでを一貫して行えます。'),
  ('33333333-3333-3333-3333-333333333333', '数百万から数千万回の読み取り/書き込みのリクエストを瞬時に処理し、時系列データやIoTセンサーデータの保存に最適な「NoSQLワイドカラム型」のデータベースはどれですか？', '["Cloud SQL", "Cloud Spanner", "Cloud Bigtable", "Memorystore"]'::jsonb, 'Cloud Bigtable', 'Cloud Bigtableは、巨大なワークロードに対して10ミリ秒未満のレイテンシで高いパフォーマンスを提供するNoSQLワイドカラムストアで、IoTや金融データなどの大量のデータストリーミングに適しています。');
